mapper.select:
select canonical_name from deployed_asset
where not is_deleted and tenant_id = #{tenant} and environment_id = #{environment}
  and asset_id = #{asset} and kind = 'DATASET'

mapper.insert:
with entries(kind, node_id, dimension_name, query_name, selector) as (values
(#{entry.kind}, #{entry.nodeId}, #{entry.dimensionName}, #{entry.queryName}, #{entry.selector})
), assets as ( insert into deployed_asset(tenant_id, owner_id, environment_id, kind, canonical_name, dimension_name) select t.tenant_id, t.manager_id, #{environment}, e.kind, e.query_name, e.dimension_name from platform_tenant t cross join entries e where not t.is_deleted and t.tenant_id = #{tenant} on conflict (tenant_id, environment_id, kind, canonical_name, dimension_name) do update set owner_id = excluded.owner_id, is_deleted = false returning tenant_id, asset_id, kind, canonical_name, dimension_name ) insert into asset_build_member(tenant_id, asset_id, build_id, query_name, selector, node_id) select a.tenant_id, a.asset_id, #{build}, e.query_name, e.selector, e.node_id from assets a join entries e on (a.kind, a.canonical_name, a.dimension_name) = (e.kind, e.query_name, e.dimension_name)

mapper.select:
with removed as (
    update asset_user_grant set is_deleted = true where not is_deleted and tenant_id = #{tenant} and user_id = #{reader} and asset_id = #{asset}
)
select exists(select from deployed_asset where not is_deleted and tenant_id = #{tenant} and asset_id = #{asset})
